canvas.addEventListener('pointerdown',e=>{if(!started||graphicsLost||$('panel').open)return;drag={id:e.pointerId,x:e.clientX,y:e.clientY,total:0,startX:e.clientX,startY:e.clientY};canvas.setPointerCapture(e.pointerId);});canvas.addEventListener('pointermove',e=>{if(!started||graphicsLost||$('panel').open||!drag||drag.id!==e.pointerId)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;tracked=null;trackedPlant=null;lockMode='auto';autoLockSuspend=.8;autoLockClock=0;drag.total+=Math.abs(dx)+Math.abs(dy);if(overview){observer.x=clamp(observer.x-dx*.14,WORLD_BOUNDS.west+.5,WORLD_BOUNDS.east-.5);observer.z=clamp(observer.z-dy*.14,WORLD_BOUNDS.south+.5,WORLD_BOUNDS.north-.5);}else{const sensitivity=binocular?.00065:magnifier?.0012:.0032;observer.yaw-=dx*sensitivity*lookSensitivity;observer.pitch=clamp(observer.pitch-dy*sensitivity*lookSensitivity,-1.2,1.2);}drag.x=e.clientX;drag.y=e.clientY;});canvas.addEventListener('pointerup',e=>{if(drag?.total<8&&nearBoard)showBoard(nearBoard);drag=null;});canvas.addEventListener('pointercancel',()=>drag=null);canvas.addEventListener('lostpointercapture',()=>drag=null);canvas.addEventListener('wheel',e=>{e.preventDefault();if(!started||graphicsLost||$('panel').open)return;if(overview)overviewHeight=clamp(overviewHeight+e.deltaY*.04,14,115);else if(binocular){$('zoom').value=clamp(Number($('zoom').value)-e.deltaY*.005,1,8);$('zoom').dispatchEvent(new Event('input'));}else if(e.deltaY< -25){setBinocular(true);}}, {passive:false});
let touchDistance=null;canvas.addEventListener('touchstart',e=>{if(started&&!graphicsLost&&!$('panel').open&&e.targetTouches.length===2)touchDistance=Math.hypot(e.targetTouches[0].clientX-e.targetTouches[1].clientX,e.targetTouches[0].clientY-e.targetTouches[1].clientY);},{passive:true});canvas.addEventListener('touchmove',e=>{if(e.targetTouches.length===2&&touchDistance){const d=Math.hypot(e.targetTouches[0].clientX-e.targetTouches[1].clientX,e.targetTouches[0].clientY-e.targetTouches[1].clientY);if(overview){overviewHeight=clamp(overviewHeight* touchDistance/d,12,115);if(overviewHeight<16)setPerspective(false);}touchDistance=d;}},{passive:true});canvas.addEventListener('touchend',()=>touchDistance=null,{passive:true});
function openPanel(eyebrow,html){resetControls();$('panel-eyebrow').textContent=eyebrow;$('panel-content').innerHTML=html;if(!$('panel').open)$('panel').showModal();$('panel').scrollTop=0;}$('close-panel').addEventListener('click',()=>$('panel').close());$('panel').addEventListener('click',e=>{if(e.target===$('panel')){const r=$('panel').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('panel').close();}});
function showPause(){openPanel('PAUSE',`<h2>Dein Rundgang ruht.</h2><p>Während du liest oder einen anderen Tab öffnest, pausiert die Simulation. Belege und Geräteexporte bleiben erhalten.</p><button id="resume-game" class="action">Erkundung fortsetzen</button>`);$('resume-game').onclick=()=>$('panel').close();}
