function showTide(){
 openPanel('NORDSEEKÜSTE · GEZEITEN',`<h2>Der Rhythmus des Watts.</h2><p>Ebbe legt den Boden frei. Flut bedeckt Nahrung und verschiebt Rastplätze. Die Tide ist zur Beobachtung auf vier Minuten verkürzt; der Bohlenweg bleibt trocken.</p><div class="tide-controls"><strong id="tide-readout"></strong><label>Position im Gezeitenzyklus<input id="tide-phase" type="range" min="0" max="100" step="1" value="${Math.round(tideClock.phase*100)}"></label><div class="panel-row"><button class="action quiet" id="low-tide">Niedrigwasser</button><button class="action quiet" id="high-tide">Hochwasser</button><button class="action" id="pause-tide"></button></div></div><p class="mini-note">Der Regler hält die Tide an. „Tide laufen lassen“ setzt sie fort. Wasserstand und Zyklus sind ein vereinfachtes Lernmodell; die Tierzeit im Fernglas beeinflusst die Tide nicht.</p>`);
 const refresh=()=>{$('tide-readout').textContent=`${tideClock.label} · ${tideClock.paused?'angehalten':'läuft'}`;$('pause-tide').textContent=tideClock.paused?'Tide laufen lassen':'Tide anhalten';landscape.update(0,tideClock.level);simulations.forEach(sim=>{sim.externalTide=tideClock.level;sim.environment.tide=['beach','wadden','saltmarsh'].includes(sim.habitat)?tideClock.level:0;sim.agents.forEach(a=>a.stateTime=0);});updatePlace();};
 $('tide-phase').addEventListener('input',e=>{tideClock.setPhase(Number(e.target.value)/100);refresh();});$('low-tide').addEventListener('click',()=>{tideClock.setPhase(0);$('tide-phase').value=0;refresh();});$('high-tide').addEventListener('click',()=>{tideClock.setPhase(.5);$('tide-phase').value=50;refresh();});$('pause-tide').addEventListener('click',()=>{tideClock.paused=!tideClock.paused;refresh();});refresh();
}
$('tide').addEventListener('click',showTide);
function faceSample(){const near=sampling.nearest(observer);setObservationTool(null);observer.yaw=Math.atan2(-(near.x-observer.x),-(near.z-observer.z));observer.pitch=-.12;if($('panel').open)$('panel').close();toast(`Folge dem Pfeil zur Bodenprobe, noch ${Math.round(near.distance)} m. Bei Wasserbedeckung zuerst Niedrigwasser einstellen.`);}
function sampleLowTide(){tideClock.setPhase(0);landscape.update(0,tideClock.level);for(const sim of simulations.values()){sim.externalTide=tideClock.level;sim.environment.tide=['beach','wadden','saltmarsh'].includes(sim.habitat)?tideClock.level:0;}showSampling();}
function showSampling(){
 const check=sampling.canDig(observer,tideClock.level),spot=check.near.original;
 openPanel('WATTBODEN · BODENPROBE',`<h2>Was lebt unter der Oberfläche?</h2><p>Gehe neben dem Bohlenweg zur runden Probenstelle. Untersuche die Oberfläche und danach tiefere Schichten. Freigelegte Tiere entdeckst du mit dem Fernglas. Eine eigene Bestimmung verlangt einen Merkmalsvergleich.</p><div class="concept" id="sample-access">${escape(check.ok?'Du stehst an der Probe. Wähle eine Untersuchungstiefe.':check.reason)} · ${Math.round(check.near.distance)} m</div><div class="sample-depths" aria-label="Untersuchungstiefe">${[0,5,10,20,30,35].map(d=>`<button type="button" class="action quiet" data-dig-depth="${d}" aria-pressed="${spot.depth===d}">${d===0?'Oberfläche':d+' cm'}</button>`).join('')}</div><div id="sample-result" role="status"></div><div class="panel-row"><button type="button" class="action quiet" id="sample-walk">Zur Bodenprobe gehen</button><button type="button" class="action quiet" id="sample-low-tide">Niedrigwasser einstellen</button></div><p class="mini-note">Graben ist an der Probenstelle bei freiliegendem Wattboden möglich. Die Grabung vertieft die Probe bis zur gewählten Tiefe; bereits entfernter Sand wird nicht zurückgefüllt. Die feste Artenauswahl und Einbautiefen sind ein Lehrmodell. Eine Untersuchung bestimmt keine Art automatisch.</p><button class="action quiet" id="sample-tide">Gezeiten einstellen</button>`);
 $('sample-tide').addEventListener('click',showTide);$('sample-walk').addEventListener('click',faceSample);$('sample-low-tide').addEventListener('click',sampleLowTide);
 const renderResult=()=>{const visible=sampling.specimens.filter(a=>a.sampleSpot===spot&&a.revealed);if(spot.depth<0)return;$('sample-result').innerHTML=`<p>${visible.length} ${visible.length===1?'Tier':'Tiere'} freigelegt · bis ${spot.depth} cm untersucht.</p>${visible.length?'<button class="action" id="sample-observe">Fund im Fernglas ansehen</button>':''}`;if(visible.length)$('sample-observe').addEventListener('click',()=>{const a=visible[0];$('panel').close();setBinocular(true);tracked=a;lockMode='manual';});};renderResult();
 $('panel-content').querySelectorAll('[data-dig-depth]').forEach(b=>b.addEventListener('click',()=>{const result=sampling.dig(observer,Number(b.dataset.digDepth),tideClock.level);if(!result.ok){$('sample-result').textContent=result.reason;return;}for(const button of $('panel-content').querySelectorAll('[data-dig-depth]'))button.setAttribute('aria-pressed',String(Number(button.dataset.digDepth)===result.depth));$('sample-access').textContent='Probe zugänglich · Wähle eine weitere Schicht oder beobachte deinen Fund.';renderResult();}));
}
$('dig').addEventListener('click',()=>sampling.nearest(observer).distance>3.8?faceSample():showSampling());
function updateSamplingHint(){const near=sampling.nearest(observer);$('dig-hint').hidden=!started||overview||$('panel').open||currentHabitat!=='wadden'||binocular||magnifier||near.distance>22;$('dig-arrow').style.transform=`rotate(${Math.atan2(near.x-observer.x,-(near.z-observer.z))+observer.yaw}rad)`;const nearby=near.distance<=3.8;$('dig-text').textContent=nearby?'Bodenprobe untersuchen':'Zur Bodenprobe gehen';$('dig').setAttribute('aria-label',nearby?'Bodenprobe untersuchen':'Zur Bodenprobe gehen');$('dig-status').textContent=`${Math.round(near.distance)} m · ${sampling.canDig(observer,tideClock.level).ok?'Probe zugänglich':nearby?'Überflutet · Niedrigwasser einstellen':'Dem Pfeil neben den Weg folgen'}`;}
function updateAutomaticFocus(dt){
 if(!(binocular||magnifier)||$('panel').open||drag||autoLockSuspend>0){autoLockClock=0;return;}
 if(tracked&&(!tracked.alive||tracked.scenarioSuppressed||tracked.scenarioInactive||Math.hypot(tracked.renderX-observer.x,tracked.renderZ-observer.z)>70||occluded(tracked.renderX,tracked.y+ANIMALS[tracked.species].size*.24,tracked.renderZ))){tracked=null;lockMode='auto';}
 if(lockMode==='manual'&&(tracked||trackedPlant))return;
 const identity=focused?.type==='animal'?`animal:${focused.item.habitat}:${focused.item.id}`:focused?`plant:${focused.item.id}:${focused.item.x}:${focused.item.z}`:null;
 if(identity!==autoLockKey){autoLockKey=identity;autoLockClock=0;}if(!focused)return;
 autoLockClock+=dt;if(autoLockClock>.28){if(focused.type==='animal'){tracked=focused.item;trackedPlant=null;}else{trackedPlant=focused;tracked=null;}}
}

function updateKnownLabels(dt){
 const entryKey=focused?.item.species||focused?.item.id,entryVisible=started&&!overview&&!$('panel').open&&(binocular||magnifier)&&!!journal.entries[entryKey];$('focus-entry').hidden=!entryVisible;if(entryVisible){$('focus-entry').dataset.species=entryKey;$('focus-entry').setAttribute('aria-label',`Feldbucheintrag ${ANIMALS[entryKey]?.common||PLANTS[entryKey]?.common} ansehen`);}
 labelsClock-=dt;if(labelsClock>0)return;labelsClock=.25;if(!(binocular||magnifier)||!started||$('panel').open){$('known-labels').innerHTML='';return;}
 const items=binocular?agents.filter(a=>a.alive&&!a.scenarioSuppressed&&!a.scenarioInactive&&journal.entries[a.species]).map(a=>({key:a.species,x:a.renderX,z:a.renderZ,y:a.y+ANIMALS[a.species].size*.65})):(focused?.type==='plant'&&journal.entries[focused.item.id]?[focused.item]:[]).map(p=>({key:p.id,x:p.x,z:p.z,y:p.y+(PLANTS[p.id].type==='tree'?1.8:p.size*.8)}));
 const uiBoxes=['field-dock','quest-guide','focus-panel','detail-loupe','zoom-control','discovery-card'].map(id=>$(id)).filter(e=>e&&!e.hidden&&e.getClientRects().length).map(e=>e.getBoundingClientRect());
 const shown=new Set(),labels=[];items.sort((a,b)=>Math.hypot(a.x-observer.x,a.z-observer.z)-Math.hypot(b.x-observer.x,b.z-observer.z));for(const p of items){if(binocular&&focused?.type==='animal'&&focused.item.species===p.key||shown.has(p.key)||labels.length>=10||Math.hypot(p.x-observer.x,p.z-observer.z)>55)continue;point.set(p.x,p.y,p.z).project(camera);if(point.z< -1||point.z>1||Math.abs(point.x)>.72||Math.abs(point.y)>.65||occluded(p.x,p.y,p.z))continue;const x=(point.x+1)*innerWidth/2,y=(1-point.y)*innerHeight/2,w=(ANIMALS[p.key]||PLANTS[p.key]).common.length*5.2+14;if(uiBoxes.some(r=>x+w/2>r.left-5&&x-w/2<r.right+5&&y+8>r.top-5&&y-17<r.bottom+5))continue;if(labels.some(l=>Math.hypot(l.x-x,l.y-y)<55))continue;shown.add(p.key);labels.push({x,y,key:p.key});}
 $('known-labels').innerHTML=labels.map(p=>`<span class="known-label" style="left:${p.x}px;top:${p.y}px">${escape((ANIMALS[p.key]||PLANTS[p.key]).common)}</span>`).join('');
}

stats();requestAnimationFrame(frame);
window.addEventListener('error',e=>{console.error(e.error||e.message);$('loading').textContent='Die Landschaft konnte nicht vollständig geladen werden. Bitte neu laden.';});

// Nearby, visible residents offer a deliberate conversation above their heads.
let residentClock=0;const residentPoint=new THREE.Vector3();
$('residents').innerHTML=landscape.residents.map(p=>`<button class="resident-talk" data-person="${p.id}" hidden aria-label="Mit ${escape(p.name)} sprechen">${escape(p.name)} · Ansprechen</button>`).join('');
$('residents').querySelectorAll('[data-person]').forEach(button=>button.addEventListener('click',()=>showResident(landscape.residents.find(p=>p.id===button.dataset.person))));
function updateResidents(dt){
 residentClock-=dt;if(residentClock>0)return;residentClock=.15;
 for(const p of landscape.residents){const button=$('residents').querySelector(`[data-person="${p.id}"]`),d=Math.hypot(p.x-observer.x,p.z-observer.z);residentPoint.set(p.x,p.y+p.height+.15,p.z).project(camera);
  const visible=started&&!overview&&!binocular&&!magnifier&&!$('panel').open&&d<4.5&&residentPoint.z>-1&&residentPoint.z<1&&Math.abs(residentPoint.x)<.82&&Math.abs(residentPoint.y)<.85&&!occluded(p.x,p.y+1.4,p.z);
  button.hidden=!visible;if(visible){button.style.left=`${(residentPoint.x+1)*innerWidth/2}px`;button.style.top=`${(1-residentPoint.y)*innerHeight/2}px`;}
 }
}
function showResident(p){
 openPanel('GESPRÄCH IM DORF',`<h2>${escape(p.name)}</h2><p class="mini-note">${escape(p.role)} · ${p.house===landscape.hives[0].house?'Am Bienenstock':'Im eigenen Vorgarten'}</p><p class="resident-greeting">„${escape(p.greeting)}“</p><p>${escape(p.tip)}</p><div class="panel-row">${p.action?`<button id="resident-action" class="action">${escape(p.action)}</button>`:''}<button id="resident-farewell" class="action quiet">Bis später!</button></div>`);
 $('resident-farewell').addEventListener('click',()=>$('panel').close());
 $('resident-action')?.addEventListener('click',()=>{const destination=residentDestination(p,questBook);if(destination.view==='quest')questUI.details(destination.id,{habitat:destination.habitat});else if(destination.view==='map')showMap();else questUI.show();if(destination.message)toast(destination.message,8000);});
}
